using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.Models;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Settings.Customers;
public class IndexModel(ApplicationDbContext db,IPermissionService permissions):PageModel
{
 public IReadOnlyList<Customer> Items{get;private set;}=[];[BindProperty(SupportsGet=true)]public string? Search{get;set;}[BindProperty(SupportsGet=true)]public int PageNumber{get;set;}=1;public int TotalPages{get;private set;}public bool CanAdd{get;private set;}public bool CanUpdate{get;private set;}public bool CanDelete{get;private set;}
 public async Task OnGetAsync(){const int size=15;var q=db.Customers.AsNoTracking();if(!string.IsNullOrWhiteSpace(Search))q=q.Where(x=>x.Name.Contains(Search)||(x.Phone!=null&&x.Phone.Contains(Search)));var count=await q.CountAsync();TotalPages=Math.Max(1,(int)Math.Ceiling(count/(double)size));PageNumber=Math.Clamp(PageNumber,1,TotalPages);Items=await q.OrderBy(x=>x.Name).Skip((PageNumber-1)*size).Take(size).ToListAsync();CanAdd=await permissions.HasAsync(User,ScreenCatalog.Customers,PermissionAction.Add);CanUpdate=await permissions.HasAsync(User,ScreenCatalog.Customers,PermissionAction.Update);CanDelete=await permissions.HasAsync(User,ScreenCatalog.Customers,PermissionAction.Delete);}
 public async Task<IActionResult> OnPostDeleteAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.Customers,PermissionAction.Delete))return Forbid();var x=await db.Customers.SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return NotFound();if(await db.CustomerDeliveries.AnyAsync(d=>d.CustomerId==id)||await db.CustomerPayments.AnyAsync(p=>p.CustomerId==id)){TempData["Error"]="لا يمكن حذف عميل مرتبط بحركات.";return RedirectToPage();}x.IsDeleted=true;x.DeletedAt=DateTimeOffset.UtcNow;x.DeletedBy=User.Identity?.Name;await db.SaveChangesAsync();return RedirectToPage();}
}
